#include <cstdint>
#include <iostream>
#include <limits>
#include <queue>
#include <utility>
#include <vector>

const long long INF = std::numeric_limits<long long>::max() / 4;
const std::uint64_t MOD = 1'000'000'007;

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, m;
    std::cin >> n >> m;
    std::vector<std::vector<std::pair<int, long long>>> g(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        long long w;
        std::cin >> u >> v >> w;
        g[u - 1].emplace_back(v - 1, w);
        g[v - 1].emplace_back(u - 1, w);
    }

    std::vector<long long> dist(n, INF);
    std::vector<std::uint64_t> ways(n, 0);
    using Item = std::pair<long long, int>;
    std::priority_queue<Item, std::vector<Item>, std::greater<>> pq;
    dist[0] = 0;
    ways[0] = 1;
    pq.emplace(0, 0);

    while (!pq.empty()) {
        auto [d, v] = pq.top();
        pq.pop();
        if (d != dist[v]) continue;
        for (auto [to, w] : g[v]) {
            if (d + w < dist[to]) {
                dist[to] = d + w;
                ways[to] = ways[v];                      // the old routes are obsolete
                pq.emplace(dist[to], to);
            } else if (d + w == dist[to]) {
                ways[to] = (ways[to] + ways[v]) % MOD;   // another equally cheap one
            }
        }
    }

    std::cout << (dist[n - 1] >= INF ? 0 : ways[n - 1]) << '\n';
}
